# -*- coding: utf-8 -*-
# Technique definitions. drills: [question, correct, [wrong x3], why]; fte: [sentence with 4 [[..]], wrongIndex, why]
T = {}
T[3]=dict(n=3,name="Reason before request",
 d="Give the circumstance first so the reader understands why you are asking. The request then feels reasonable.",
 how=["Start with the situation: <i>Because… / Since… / As…</i>","Then make the request.","Keep the reason specific and short. Do not apologize again and again."],
 weak="Can I miss the Friday class? I have a medical appointment.",
 strong="Because my medical appointment cannot be moved from Friday morning, I would like to ask whether I could miss that class.",
 sample="<p><b>To:</b> prof.mendoza@univ.edu · <b>Subject:</b> Request to change my presentation date</p><p>Dear Professor Mendoza,</p><p>I am writing about my presentation scheduled for 12 March. <mark>Because I must attend a compulsory field survey on that day, I am unable to present as planned.</mark> I would therefore like to ask whether I could present on 14 March instead. I have already finished the slides and can send them to you in advance.</p><p>Thank you for considering my request.</p><p>Kind regards,<br>Lucía Parada</p><p class='small muted'>Highlighted: the reason comes first, then the request.</p>",
 drills=[
  ["Which sentence puts the reason <i>first</i>?","Since the lab closes at 5 p.m., I would like to ask whether we could start earlier.",["I would like to ask whether we could start earlier, since the lab closes at 5 p.m.","Could we start earlier? The lab closes at 5.","Please let us start earlier or we will not finish."],"The reason (<i>Since…</i>) comes before the request."],
  ["Which is the best request to a manager?","As my commute takes four hours a day, I would like to ask whether I could work from home on Fridays.",["I want to work from home on Fridays. My commute is long.","Can I work from home Fridays?","My commute is long, so give me Fridays at home."],"Reason first, then an indirect request."],
  ["Rewrite with the reason first: “I would like to request a different seminar group. My work schedule changed this week.”","Because my work schedule changed this week, I would like to request a different seminar group.",["I would like to request a different seminar group, because my work schedule changed this week.","My work schedule changed this week. A different group, please.","Please give me a different group, and my schedule changed."],"<i>Because…</i> leads the sentence."],
  ["Which reason is specific enough?","The bus to campus does not run before 9 a.m., so I cannot attend the 8 a.m. class.",["I have some problems with transport.","Things are complicated for me.","It is not convenient for me."],"It names the cause and the effect."],
  ["Which linker best introduces the reason? “___ my exams finish on 20 June, I cannot confirm my place by 10 June.”","Because",["Although","However","Unless"],"<i>Because</i> introduces a reason."]],
 fte=[["[[Since]] the library [[close]] at five, I would like to ask whether we [[could]] meet [[earlier]].",1,"<i>the library closes</i>: third person singular."],
      ["[[Because of]] my exams finish on 20 June, I [[would]] like to ask [[whether]] I [[could]] reply later.",0,"<i>Because of</i> + noun; before a clause use <i>Because</i>."]])
T[10]=dict(n=10,name="Offer an alternative or compromise",
 d="Show flexibility. If your first request is impossible, propose another solution so the reader can say yes to something.",
 how=["Use <i>If… is not possible, I would be glad to… / Alternatively, I could… / As a compromise…</i>","Make the alternative realistic and small.","Place it after the main request."],
 weak="Please change my time. If not, I will not come.",
 strong="If Thursday afternoon is already booked, we would be flexible about the hour, and we could also share equipment with another group.",
 sample="<p><b>To:</b> manager@greenfield.com · <b>Subject:</b> Request to work from home on Fridays</p><p>Dear Ms. Ibáñez,</p><p>I am writing to ask whether I could work from home on Fridays, since my commute takes four hours a day. I would use the time to complete my reports and remain available by phone and email.</p><p><mark>If a permanent arrangement is not possible, I would be glad to try it for two months so that you can assess the results.</mark></p><p>Thank you for considering this request.</p><p>Kind regards,<br>Rodrigo Salas</p><p class='small muted'>Highlighted: a realistic compromise after the main request.</p>",
 drills=[
  ["Which sentence offers a realistic alternative?","If Monday is not possible, I would be glad to meet on Tuesday morning.",["If Monday is not possible, I will not come.","Monday is the only day I accept.","You must find another day."],"It is flexible and specific."],
  ["Which is the best compromise for a request to work from home?","As a compromise, I could work remotely two Fridays a month during a trial period.",["I will work from home or I will quit.","I will decide when I work from home.","I will only come to the office on Mondays."],"A trial period is a small, realistic offer."],
  ["Which word introduces an alternative? “___, I could submit the draft on Friday.”","Alternatively",["In addition","For example","Therefore"],"<i>Alternatively</i> introduces another option."],
  ["Where should the alternative usually go?","After the main request",["Before the greeting","Instead of the request","Only in the subject line"],"Make the main request first, then offer the alternative."],
  ["Which alternative is too big for a small request?","I could also reorganize your entire department’s schedule.",["I could submit the work a day earlier.","I could send a short summary in advance.","I could attend the second session instead."],"Alternatives should be proportionate."]],
 fte=[["If a permanent arrangement [[is not]] possible, I [[would]] be [[glad]] [[to tried]] it for two months.",3,"After <i>glad to</i>, use the base verb: <i>to try</i>."],
      ["[[Alternatively]], I [[could]] [[to send]] the documents [[today]].",2,"After <i>could</i>, use the base verb: <i>send</i>."]])
T[6]=dict(n=6,name="Neutral facts instead of blame",
 d="State what happened with dates, numbers and objects, not who is bad. Facts are harder to argue with and keep the tone professional.",
 how=["Use neutral subjects: <i>The order arrived incomplete.</i>","Give dates and numbers: <i>order 8841, 9 March</i>.","Avoid <i>you always, you never, terrible, ruined</i>.","Express concern with one hedged sentence: <i>I was disappointed to find…</i>"],
 weak="You ruined my order and your service is terrible.",
 strong="The order that arrived on Monday was incomplete: one of the three textbooks was missing.",
 sample="<p><b>To:</b> support@onlinebooks.com · <b>Subject:</b> Incomplete order 8841</p><p>Dear Customer Service,</p><p>I am writing about order 8841, placed on 2 March. <mark>The package that arrived on 9 March contained two of the three textbooks I ordered; the third, Statistics for the Social Sciences, was missing.</mark> I was disappointed to find this, because the term began on 6 March and I need the book for next week’s class. I would be grateful if you could send the missing book by express delivery or refund it.</p><p>Thank you for your help.</p><p>Kind regards,<br>Andrea Montaño</p><p class='small muted'>Highlighted: facts only. Dates, numbers and the title, with no blame.</p>",
 drills=[
  ["Which sentence is neutral?","The ceiling in my bathroom has been damaged since 12 May.",["Your building is a disaster.","You never repair anything.","The landlord is lazy."],"It states a fact and a date."],
  ["Which is the best neutral version of “You charged me twice, you are thieves!”?","My card was charged twice on 3 June for the same membership.",["You made a stupid mistake.","I am furious about your company.","Your company always charges customers twice."],"Facts, with no accusation."],
  ["Which detail makes a complaint stronger?","Order number 4471, placed on 5 March",["a long time ago","many problems","something bad"],"Specific details can be checked."],
  ["Which sentence expresses concern without blame?","I was disappointed to find that no alternative room was offered.",["It is outrageous that you offered nothing.","You should be ashamed of this service.","I hate this hotel."],"A hedged feeling, linked to a fact."],
  ["Which sentence contains blame?","You did not care about your customers.",["The package arrived on 9 March.","The second book was missing.","No reply has been received since 15 May."],"It judges the person, not the facts."]],
 fte=[["The package [[that]] [[arriving]] on 9 March [[contained]] only [[two books]].",1,"<i>that arrived</i>: use the past tense in a relative clause."],
      ["My card [[was]] [[charged]] twice [[in]] 3 June for the same [[membership]].",2,"Use <i>on</i> with a date."]])
T[4]=dict(n=4,name="End with the next step",
 d="Close by saying exactly what you want to happen next, and by when, so the reader knows how to respond.",
 how=["Name the action: <i>a refund, a repair, a meeting</i>.","Give a date or time frame: <i>by 30 May, within ten days</i>.","Offer your cooperation: <i>I can send… / I am available…</i>","Finish with courtesy: <i>I look forward to your reply.</i>"],
 weak="Please answer me soon.",
 strong="I would be grateful if you could confirm the refund by Friday 14 June. I can send the receipt today.",
 sample="<p><b>To:</b> landlord@homes.com · <b>Subject:</b> Water damage in my bathroom</p><p>Dear Mr. Suárez,</p><p>I am writing about water damage in my bathroom. The ceiling has been stained since a leak from the apartment above began on 12 May, and I reported it to you on 15 May. I am concerned that the damage may spread.</p><p><mark>I would be grateful if the repair could be completed by 30 May, and I am happy to be at home any weekday afternoon to give the plumber access.</mark> I look forward to hearing from you.</p><p>Kind regards,<br>Elena Vargas</p><p class='small muted'>Highlighted: an action, a date and an offer to cooperate.</p>",
 drills=[
  ["Which closing gives a clear next step?","Could you confirm the repair date by Friday? I can be at home on weekday afternoons.",["Please do something about it.","I hope things get better.","Thank you, goodbye."],"Action, date and cooperation."],
  ["Which phrase adds a time frame?","by 14 June",["sometime","when you can","as soon as possible maybe"],"A date lets the reader plan."],
  ["Which is the best final sentence for a refund request?","I would appreciate written confirmation of the refund within ten days.",["Please do the right thing.","I will think about my next step.","That is all."],"It names the action and the time frame."],
  ["Which sentence offers cooperation?","I can send a copy of the receipt today.",["You should already have it.","I will not send any documents.","It is not my problem."],"It makes the next step easy."],
  ["Which closing is too vague?","Please reply when you can.",["Please reply by Thursday 12 June.","Could we meet on Friday morning?","I can send the documents today."],"“When you can” gives no time frame."]],
 fte=[["I would be grateful if the repair [[could]] [[completed]] [[by]] 30 May and I [[am]] happy to help.",1,"Passive: <i>could be completed</i>."],
      ["I look [[forward]] [[to hear]] [[from]] you [[by]] Friday.",1,"<i>look forward to</i> + <i>-ing</i>: <i>hearing</i>."]])
T[8]=dict(n=8,name="Benefit to the reader",
 d="Persuade by showing how the change helps the person who decides, not only you.",
 how=["Ask: what does the reader gain? <i>time, money, reputation, quality</i>.","Use <i>This would allow you to… / This would benefit both students and staff.</i>","Support the benefit with a fact or a number.","Link the benefit to the reader’s goals."],
 weak="I want flexible hours because I like to sleep late.",
 strong="Flexible hours would reduce lateness caused by traffic and help the company keep experienced staff.",
 sample="<p><b>To:</b> hr@mediacorp.com · <b>Subject:</b> Proposal for a flexible-hours pilot</p><p>Dear Ms. Antezana,</p><p>I am writing to propose a flexible-hours pilot for our office. <mark>Allowing staff to start between 8 and 10 a.m. would reduce lateness caused by traffic and help the company keep experienced employees, who often cite commuting as a reason to leave.</mark> Phone coverage could still run until 6 p.m. if late starters finish later. I would be glad to draft a three-month trial for your review.</p><p>Thank you for considering this proposal.</p><p>Kind regards,<br>Gabriel Ortiz</p><p class='small muted'>Highlighted: benefits for the company, not only for the writer.</p>",
 drills=[
  ["Which reason focuses on the <i>reader’s</i> benefit?","Conversation clubs would raise student satisfaction and help the center attract new students.",["I would enjoy speaking English.","I am bored in grammar classes.","My friends want conversation clubs too."],"It names a gain for the center."],
  ["Reader: the mayor. Which benefit is strongest?","More recycling bins would reduce litter and lower street-cleaning costs for the city.",["I like clean streets.","Recycling is popular.","I walk past the park every day."],"It links to the mayor’s goals and budget."],
  ["Which phrase presents a benefit for the reader?","This would allow the library to serve students who work during the day.",["This would allow me to study.","I would be happier.","Many people are tired."],"The library gains something."],
  ["Which is the best sentence after “I propose extending library hours”?","This would help students who work during the day prepare for examinations.",["I think libraries are nice.","I do not like noisy cafés.","Hours are important."],"It names who benefits and how."],
  ["Which reason is too personal for a persuasive email to a director?","I would not have to wake up early.",["It would help staff arrive on time.","It would reduce stress and absences.","It would make the center more attractive."],"It benefits only the writer."]],
 fte=[["[[Flexible]] hours would [[reduce]] lateness and [[helps]] the company [[retain]] staff.",2,"<i>would reduce … and help</i>: the same verb form."],
      ["This [[would]] [[allow]] the library [[serving]] students [[who]] work.",2,"<i>allow … to serve</i>."]])
T[9]=dict(n=9,name="Anticipate the objection",
 d="Mention the most likely concern before the reader raises it, and answer it, so your proposal looks realistic.",
 how=["Ask: what will they worry about? <i>cost, time, safety</i>.","Use <i>You may be concerned that… However…</i>","Answer with a fact or a small commitment.","Keep it to one or two sentences."],
 weak="It will be great and nobody will have any problem.",
 strong="The additional cost would be modest, since only one floor and two staff members would be involved.",
 sample="<p><b>To:</b> director@languagecenter.org · <b>Subject:</b> Suggestion: weekly conversation clubs</p><p>Dear Mr. Camacho,</p><p>I am writing to suggest weekly conversation clubs at the center. Students currently practice grammar but have few chances to speak, so clubs would help them gain confidence and make the center more attractive to new learners. <mark>You may be concerned about staffing; however, the clubs could be led by volunteer teachers for one hour on Saturdays, which would add no salary cost.</mark> I would be happy to help organize the first sessions.</p><p>Thank you for your time.</p><p>Kind regards,<br>Natalia Ríos</p><p class='small muted'>Highlighted: the objection (staffing) and the answer.</p>",
 drills=[
  ["Which sentence anticipates an objection?","You may be concerned about cost; however, the plan needs only one volunteer.",["This plan is perfect.","I think everyone will love it.","Nobody will complain."],"It names the worry and answers it."],
  ["What is a likely objection to longer library hours?","Staffing costs",["The color of the building","The weather","The price of paper"],"Cost and staffing are the obvious concerns."],
  ["Which answer to a safety concern is best?","Two adults would supervise the clean-up and gloves would be provided.",["Safety is not a problem.","Nobody gets hurt in parks.","I am very careful."],"It gives a concrete safeguard."],
  ["Which phrase introduces an objection politely?","You may be concerned that…",["I am sure that…","Everybody agrees that…","Obviously, …"],"It acknowledges the reader’s view."],
  ["Where is the objection usually best placed?","After the reasons and before the closing",["Before the greeting","In the subject line","After the signature"],"Reasons first, then the concern, then the call to action."]],
 fte=[["You [[may]] be concerned [[about]] cost; [[however]], the plan [[need]] only one volunteer.",3,"<i>the plan needs</i>."],
      ["[[Some]] readers [[might]] worry [[that]] the clubs [[is]] expensive.",3,"<i>the clubs are</i>."]])
T[7]=dict(n=7,name="Match greeting, closing and register to the reader",
 d="The reader decides the greeting, the closing and the vocabulary. Never mix formal and informal choices in one email.",
 how=["Professor or official: <i>Dear Professor Lara, … Yours sincerely,</i>","Colleague: <i>Hello Sami, … Best wishes,</i>","Friend: <i>Hi Sami, … See you soon!</i>","Match contractions and vocabulary to the greeting."],
 weak="Hey Professor, give me my mark ASAP. Cheers!",
 strong="Dear Professor Lara, I would like to ask about my mark. Kind regards,",
 sample="<p><b>To:</b> prof.lara@univ.edu · <b>Subject:</b> Query regarding my midterm mark</p><p><mark>Dear Professor Lara,</mark></p><p>Thank you for returning the exams so promptly. I am writing to ask about the mark I received for the second question, as I may have misunderstood a point in the grading. I would be grateful for any clarification you could offer.</p><p><mark>Yours sincerely,</mark><br>Pablo Rojas</p><p class='small muted'>Highlighted: formal greeting and closing that match the vocabulary of the whole email.</p>",
 drills=[
  ["Which greeting is best for a professor you have not met?","Dear Professor Lara,",["Hey Lara!","Hi guys,","Yo professor,"],"Title + surname."],
  ["Which closing is best for a formal email to a dean?","Yours sincerely,",["See ya!","Bye bye,","Cheers mate,"],"Formal closing for a formal reader."],
  ["Which message mixes registers?","Dear Dr. Salvatierra, I can’t make it on Friday, sorry!",["Dear Dr. Salvatierra, I regret that I will be unable to attend on Friday.","Hi Sami, I can’t make it on Friday, sorry!","Hello Sami, I won’t be able to attend on Friday."],"A formal greeting with casual wording."],
  ["Which message suits a close classmate?","Hi Sami, can you take notes for me on Friday?",["Dear Mr. Sami, I would be grateful if you could kindly provide notes.","To whom it may concern, notes are requested.","Respected colleague, kindly supply notes."],"Informal for a friend."],
  ["Which closing suits a colleague?","Best wishes,",["Yours faithfully,","Respectfully yours,","Yours truly, esteemed colleague,"],"Neutral and friendly."]],
 fte=[["[[Dear]] Dr. Salvatierra, I [[regret]] that I [[can’t]] attend, and I [[apologize]] for the inconvenience.",2,"Avoid contractions in a formal email: <i>will be unable to attend</i>."],
      ["[[Dear]] Professor Lara, [[thanks]] a lot for the exam. I would be [[grateful]] for your [[advice]].",1,"<i>thanks a lot</i> is informal: use <i>thank you</i>."]])
T[11]=dict(n=11,name="Specific details",
 d="Precise details (dates, numbers, names, documents) make your email believable and easier to act on.",
 how=["Name the course, date, amount or document.","Quote the rule or message you refer to.","Replace <i>a few days ago</i> with <i>on 12 May</i>.","Check that each bullet has at least one detail."],
 weak="I withdrew a long time ago and they charged me a lot.",
 strong="I withdrew from Macroeconomics on 3 March, before the 10 March deadline, but I was charged the full fee of 4,200 Bs.",
 sample="<p><b>To:</b> registrar@univ.edu · <b>Subject:</b> Withdrawal fee charged in error</p><p>Dear Registrar,</p><p>I am writing about my withdrawal from Macroeconomics. <mark>I withdrew on 3 March, before the 10 March deadline, and my advisor, Dr. Paz, confirmed the withdrawal by email on 4 March; however, I was charged the full tuition fee of 4,200 Bs.</mark> I believe this may be an error. I can send the email confirmation and my payment receipt today, and I would appreciate a correction by 25 March.</p><p>Thank you for your help.</p><p>Yours sincerely,<br>Mateo Flores</p><p class='small muted'>Highlighted: course, dates, name, amount.</p>",
 drills=[
  ["Which sentence is more specific?","I withdrew from Macroeconomics on 3 March.",["I withdrew some time ago.","I left the course recently.","I did what I had to do."],"Course and date."],
  ["Which detail is most useful in a complaint about a late order?","the order number",["your opinion of the shop","the weather that day","my favorite author"],"The reader can find the order."],
  ["Replace the vague phrase: “I wrote to you a few days ago.”","I wrote to you on 15 May.",["I wrote to you some days before.","I wrote to you in the past.","I wrote to you before."],"A date is precise."],
  ["Which sentence quotes a source precisely?","The syllabus says the paper must be “between 8 and 10 pages”, but the rubric says “10 to 12 pages”.",["The instructions are confusing.","Everything seems different.","Nobody knows the length."],"It names both documents and numbers."],
  ["Which sentence has the weakest detail?","I have had some problems with the course recently.",["I missed the quiz on 4 April because of a bus strike.","My grade for question 2 was 5/10.","I emailed Dr. Paz on 4 March."],"“Some problems … recently” says nothing precise."]],
 fte=[["I [[withdrew]] from Macroeconomics [[at]] 3 March, [[before]] the 10 March [[deadline]].",1,"Use <i>on</i> with a date."],
      ["My advisor [[confirm]] the withdrawal [[by email]] on 4 March, [[but]] I was [[charged]] the full fee.",0,"<i>confirmed</i>: past tense."]])
T[12]=dict(n=12,name="Link your sentences",
 d="Connectors show how each sentence relates to the last (reason, contrast, result, addition), so the email reads as one message and not a list.",
 how=["Reason: <i>because, since, as</i>. Contrast: <i>however, although</i>.","Result: <i>therefore, as a result</i>. Addition: <i>in addition, moreover</i>.","Use one connector for each relationship.","Vary the position: start, middle or after a semicolon."],
 weak="I cannot accept. I have two projects. I could suggest Ms. Rojas.",
 strong="I regret that I cannot accept because I have two projects running until November; however, I could recommend Ms. Rojas.",
 sample="<p><b>To:</b> director@brightmedia.com · <b>Subject:</b> Re: Invitation to lead the redesign</p><p>Dear Ms. Calvo,</p><p>Thank you for inviting me to lead the redesign of the website. I regret that I will be unable to accept <mark>because</mark> two client projects run until November. <mark>As a result</mark>, I could not give the redesign the attention it deserves. <mark>However</mark>, I would be glad to reconsider in December, and <mark>in addition</mark> I could recommend Ms. Rojas, whose portfolio includes similar work.</p><p>Thank you again for your confidence.</p><p>Yours sincerely,<br>Fernando Méndez</p><p class='small muted'>Highlighted: reason, result, contrast and addition.</p>",
 drills=[
  ["Best connector: “I cannot attend; ___, I would like the materials.”","however",["because","therefore","for example"],"Contrast."],
  ["Best connector: “Two projects run until November; ___, I cannot accept.”","therefore",["although","however","unless"],"Result."],
  ["Which connector adds an idea?","in addition",["although","because","however"],"Addition."],
  ["Which version flows best?","I cannot attend the workshop because my train arrives late; however, I would be grateful for the materials.",["I cannot attend the workshop. My train arrives late. I would be grateful for the materials.","I cannot attend the workshop, because, however, I would be grateful for the materials.","I cannot attend the workshop therefore my train arrives late although the materials."],"Each connector matches its relationship."],
  ["Which sentence uses a connector incorrectly?","I enjoy the course; therefore, the lectures are difficult.",["I enjoy the course; however, the lectures are difficult.","The lectures are difficult; therefore, I study every day.","I enjoy the course because the lectures are clear."],"<i>therefore</i> shows a result, and “enjoy” is not the cause of “difficult”."]],
 fte=[["I regret that I cannot accept [[because of]] I have two projects; [[however]], I could [[recommend]] [[a colleague]].",0,"<i>Because of</i> + noun; before a clause use <i>because</i>."],
      ["The costs are low; [[therefore]], I [[recommend]] the plan; [[however]], it [[would helps]] students.",3,"<i>would help</i>."]])
