REV13=[
 ["Which technique does this sentence use? “I am writing to decline your invitation to speak at the conference in La Paz.”","Purpose in sentence 1",["Benefit to the reader","Offer an alternative or compromise","Link your sentences"],"It states the purpose at once."],
 ["Which technique does this sentence use? “If the timeline were flexible, I would be glad to reconsider in December.”","Offer an alternative or compromise",["Anticipate the objection","Specific details","Soften your requests"],"A conditional alternative."],
 ["Which technique does this sentence use? “You may be concerned about cost; however, the plan needs only one volunteer.”","Anticipate the objection",["Benefit to the reader","Reason before request","End with the next step"],"It names the worry and answers it."],
 ["Which technique does this sentence use? “The package that arrived on 9 March contained two of the three books.”","Neutral facts instead of blame",["Soften your requests","Benefit to the reader","Match the register"],"Facts and a date, no blame."],
 ["Which technique does this sentence use? “I would be grateful if you could confirm the date by Friday.”","End with the next step",["Reason before request","Anticipate the objection","Link your sentences"],"An action and a time frame."],
 ["Which technique does this sentence use? “This would allow the library to serve students who work during the day.”","Benefit to the reader",["Neutral facts instead of blame","Purpose in sentence 1","Specific details"],"It shows what the reader gains."]]
REV15=[
 ["Which version is for a <i>senior official</i>?","I regret that I will be unable to attend Friday’s workshop.",["I can’t make it on Friday, sorry!","I won’t be able to join on Friday.","No Friday for me, sorry."],"Formal vocabulary, no contractions."],
 ["Which email mixes registers?","Dear Professor Zambrana, I can’t make the workshop, sorry. Cheers!",["Dear Professor Zambrana, I regret that I cannot attend. Kind regards,","Hi Sami, I can’t make the workshop, sorry. See you soon!","Hello Sami, I won’t be able to attend. Best wishes,"],"Formal greeting with casual body and closing."],
 ["Which greeting fits a close classmate?","Hi Sami,",["Dear Mr. Sami,","To whom it may concern,","Dear esteemed colleague,"],"Informal for a friend."],
 ["Which closing fits a supervisor you do not know well?","Kind regards,",["See you!","Cheers mate,","Bye for now,"],"Polite and neutral."],
 ["Which technique is missing from this opening? “Hi Dr. Zambrana, I hope you are well and having a good day. My train arrives late on Fridays…”","Purpose in sentence 1",["Benefit to the reader","Link your sentences","Offer an alternative or compromise"],"The purpose is not stated at the start."],
 ["A senior reader, a report that will be one day late. Which opening is best?","I am writing to inform you that the client report will be delivered one day late.",["I hope you are well and have a lot of work.","Something happened with the report.","Hi boss, quick news!"],"Purpose first, formal register."]]
